import { Link } from "react-router-dom";

export default function DeliveryInfo() {
  return (
    <div className="max-w-4xl mx-auto px-4 py-10 text-[#2D1E16]">
      <Link to="/" className="text-[#D97706] font-semibold">← Back to Home</Link>
      <h1 className="font-display text-3xl font-bold mt-4">Delivery Info</h1>
      <div className="mt-6 space-y-4 text-sm leading-7 text-[#5C4A3D]">
        <p>We deliver fresh bakery items within our service area in and around Bangalore.</p>
        <p>Delivery is available daily between 11:00 AM and 11:00 PM.</p>
        <p>Estimated delivery time is usually within 25 minutes depending on the location and order volume.</p>
        <p>Please ensure your phone number is active so our delivery team can contact you if needed.</p>
        <p>For any delivery concerns, please contact us at slvbakery@gmail.com or call +91 81056 52158.</p>
      </div>
    </div>
  );
}
